input.newString:
def apply_batch(inventory, adjustments):
    # Validate all adjustments first
    for sku, delta in adjustments:
        if sku not in inventory.quantities:
            return False
        if inventory.quantities[sku] + delta < 0:
            return False

    # Apply all adjustments if validation passes
    for sku, delta in adjustments:
        inventory.quantities[sku] += delta
    return True
